package com.studenttracker.service;
import com.studenttracker.database.DatabaseManager; import com.studenttracker.model.*; import com.studenttracker.util.InputValidator; import java.sql.*; import java.time.LocalDate; import java.util.*;
public class TaskService { private final DatabaseManager db; public TaskService(DatabaseManager db){this.db=db;} public int add(Task t)throws SQLException{InputValidator.requireText(t.getTitle(),"Title");InputValidator.requireText(t.getSubject(),"Subject");InputValidator.requireHours(t.getEstimatedHours());String q="INSERT INTO tasks(title,subject,description,priority,deadline,estimated_hours,status) VALUES(?,?,?,?,?,?,?)";try(PreparedStatement p=db.getConnection().prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setString(1,t.getTitle());p.setString(2,t.getSubject());p.setString(3,t.getDescription());p.setString(4,t.getPriority().name());p.setString(5,t.getDeadline().toString());p.setDouble(6,t.getEstimatedHours());p.setString(7,t.getStatus().name());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next()){t.setId(r.getInt(1));return t.getId();}}}return 0;}
 public List<Task> all()throws SQLException{return query("SELECT * FROM tasks ORDER BY deadline, priority DESC");} public List<Task> pending()throws SQLException{return query("SELECT * FROM tasks WHERE status <> 'COMPLETED' ORDER BY deadline, priority DESC");} public void complete(int id)throws SQLException{updateStatus(id,TaskStatus.COMPLETED);} public void start(int id)throws SQLException{updateStatus(id,TaskStatus.IN_PROGRESS);} private void updateStatus(int id,TaskStatus s)throws SQLException{try(PreparedStatement p=db.getConnection().prepareStatement("UPDATE tasks SET status=? WHERE id=?")){p.setString(1,s.name());p.setInt(2,id);if(p.executeUpdate()==0)throw new IllegalArgumentException("Task not found: "+id);}} public void delete(int id)throws SQLException{try(PreparedStatement p=db.getConnection().prepareStatement("DELETE FROM tasks WHERE id=?")){p.setInt(1,id);if(p.executeUpdate()==0)throw new IllegalArgumentException("Task not found: "+id);}}
 private List<Task> query(String q)throws SQLException{List<Task> out=new ArrayList<>();try(PreparedStatement p=db.getConnection().prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next())out.add(new Task(r.getInt("id"),r.getString("title"),r.getString("subject"),r.getString("description"),Priority.valueOf(r.getString("priority")),LocalDate.parse(r.getString("deadline")),r.getDouble("estimated_hours"),TaskStatus.valueOf(r.getString("status"))));}return out;}
}
